<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {ScheduledLoopsController,LoopsError,type ScheduledLoopsPort,type LoopSnapshot,type ScheduledLoop,type LoopPatch,type LoopRun} from './scheduled-loops';import '../automations/automations.css';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;export let api:ScheduledLoopsPort|undefined=undefined;
 const dispatch=createEventDispatcher<{close:void;denied:{status:number};openConversation:{conversationId:string};changed:{companyId:string;loopId:string}}>();
 let mounted=false,scope='',watched:AbortSignal|undefined,port:ScheduledLoopsPort|undefined,client:ScheduledLoopsController|undefined,generation=0,session='';
 let snapshot:LoopSnapshot|null=null,loading=true,busy=false,error='',notice='',query='',selectedId='',editing=false,base:ScheduledLoop|null=null,patch:LoopPatch|null=null,conflict=false,confirm:'delete'|'activate'|'resume'|null=null,consent=false,pendingSelection:string|null=null,runs:LoopRun[]|null=null;
 $: selected=snapshot?.items.find(l=>l.id===selectedId)||null;
 $: filtered=(snapshot?.items||[]).filter(l=>(l.name+' '+l.ownerBot.name+' '+l.status+' '+l.destinations.map(d=>d.label+' '+d.platform).join(' ')).toLowerCase().includes(query.toLowerCase()));
 $: dirty=!!editing&&!!base&&!!patch&&JSON.stringify(patch)!==JSON.stringify(toPatch(base));
 $: if(mounted&&(scope!==companyId+'\0'+actorId||watched!==accessSignal||port!==api)){reset();scope=companyId+'\0'+actorId;watched=accessSignal;port=api;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else if(port){session=localStorage.getItem('token')||'';client=new ScheduledLoopsController(companyId,actorId,port,()=>localStorage.getItem('token')||'',watched);void load();}else loading=false;}
 function reset(){generation++;client?.close();client=undefined;watched?.removeEventListener('abort',lost);snapshot=null;loading=true;busy=false;error='';notice='';selectedId='';editing=false;base=null;patch=null;conflict=false;confirm=null;consent=false;pendingSelection=null;runs=null;query='';}
 function lost(){reset();loading=false;dispatch('close');}
 function fail(cause:unknown){const status=(cause as {status?:number})?.status;if(status===401||status===403){lost();dispatch('denied',{status});return;}if(status===409){conflict=true;error='This loop changed on the server. Your unsaved draft is kept. Refresh and review the latest revision before continuing.';return;}error=cause instanceof LoopsError?cause.message:'The loop change could not be confirmed. Refresh its saved state before trying again.';}
 function toPatch(loop:ScheduledLoop):LoopPatch{return {name:loop.name,text:loop.text,destinationIds:loop.destinations.map(d=>d.id),mediaIds:loop.media.map(m=>m.id),schedule:{...loop.schedule}};}
 async function load(){if(!client)return;const n=generation,current=client;loading=true;error='';try{const value=await current.snapshot();if(n!==generation)return;snapshot=value;if(editing&&base){const latest=value.items.find(l=>l.id===base?.id);if(!latest||latest.revision!==base.revision)conflict=true;}if(selectedId&&!value.items.some(l=>l.id===selectedId)){selectedId='';runs=null;}}catch(e){if(n===generation)fail(e);}finally{if(n===generation)loading=false;}}
 function choose(id:string){if(dirty){pendingSelection=id;return;}selectedId=id;editing=false;base=null;patch=null;conflict=false;confirm=null;consent=false;runs=null;}
 function edit(loop:ScheduledLoop){base=loop;patch=toPatch(loop);editing=true;conflict=false;confirm=null;runs=null;}
 async function action(task:(current:ScheduledLoopsController,n:number)=>Promise<void>){if(!client||busy)return;const n=generation,current=client;busy=true;error='';notice='';try{await task(current,n);}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 function apply(loop:ScheduledLoop){if(!snapshot)return;snapshot={...snapshot,items:snapshot.items.map(l=>l.id===loop.id?loop:l)};confirm=null;consent=false;dispatch('changed',{companyId,loopId:loop.id});}
 async function save(){if(!base||!patch||conflict)return;const currentBase=base,draft=structuredClone(patch);await action(async(current,n)=>{const value=await current.update(currentBase,draft);if(n!==generation)return;apply(value);editing=false;base=null;patch=null;notice='Loop changes saved. Review any renewed publishing authorization before it runs.';});}
 async function pause(loop:ScheduledLoop){await action(async(current,n)=>{const value=await current.pause(loop);if(n!==generation)return;apply(value);notice='Saved loop pause confirmed.';});}
 async function resume(loop:ScheduledLoop){await action(async(current,n)=>{const value=await current.resume(loop);if(n!==generation)return;apply(value);notice='Saved loop resume confirmed.';});}
 async function activate(loop:ScheduledLoop){if(!consent)return;await action(async(current,n)=>{const value=await current.activate(loop);if(n!==generation)return;apply(value);notice='Publishing authorization recorded for the reviewed loop rules.';});}
 async function remove(loop:ScheduledLoop){await action(async(current,n)=>{await current.remove(loop);if(n!==generation||!snapshot)return;snapshot={...snapshot,items:snapshot.items.filter(l=>l.id!==loop.id)};selectedId='';confirm=null;editing=false;base=null;patch=null;runs=null;notice='Loop deletion confirmed.';dispatch('changed',{companyId,loopId:loop.id});});}
 async function history(loop:ScheduledLoop){await action(async(current,n)=>{const values=await current.history(loop);if(n===generation&&selectedId===loop.id)runs=values;});}
 function checkSession(){if(client&&session!==(localStorage.getItem('token')||''))lost();}function storage(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 const date=(n:number|null)=>n===null?'Not available':new Date(n*1000).toLocaleString();
 onMount(()=>{mounted=true;window.addEventListener('storage',storage);const timer=setInterval(checkSession,500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('storage',storage);});
</script>
<section class="starli-automations loops" aria-label="Scheduled Loops"><button class="back" on:click={()=>{if(dirty)pendingSelection='__close';else dispatch('close');}}>← Back to workspace</button><header class="sa-heading"><div><span class="sa-eyebrow">COMPANY AUTOMATIONS</span><h1>Scheduled Loops</h1><p class="sa-muted">Bots prepare recurring work in chat. Review the rules, manage its schedule and follow verified results here.</p></div><button disabled={busy||loading||!client} on:click={()=>void load()}>Refresh</button></header>{#if error}<p class="sa-error" role="alert">{error}</p>{/if}{#if notice}<p class="sa-muted" role="status">{notice}</p>{/if}
 {#if pendingSelection}<div class="sa-confirm"><strong>Discard unsaved changes?</strong><p class="sa-muted">Your saved loop stays unchanged.</p><div class="sa-actions"><button on:click={()=>pendingSelection=null}>Keep editing</button><button class="sa-danger" on:click={()=>{const target=pendingSelection;pendingSelection=null;editing=false;base=null;patch=null;if(target==='__close')dispatch('close');else if(target)choose(target);}}>Discard draft</button></div></div>{/if}
 {#if !api}<div class="sa-empty"><h2>Scheduled Loops unavailable</h2><p class="sa-muted">The native company scheduler has not been connected to this screen. No recurring work is created or started here.</p></div>{:else if loading&&!snapshot}<p class="sa-muted" role="status">Loading saved company loops…</p>{:else if snapshot}<label class="sa-label search">Find a loop<input class="sa-input" type="search" bind:value={query} placeholder="Name, bot, platform or status"/></label><div class="layout"><div class="loop-list">{#each filtered as loop}<button class:chosen={selectedId===loop.id} class="loop-row" on:click={()=>choose(loop.id)} disabled={busy}><span><strong>{loop.name}</strong><small>{loop.ownerBot.name} · {loop.destinations.map(d=>d.platform).join(', ')}</small><small>Next: {date(loop.nextDueAt)}</small></span><span class="sa-badge">{loop.status.replaceAll('_',' ').toLowerCase()}</span></button>{:else}<div class="sa-empty"><h3>{query?'No matching loops':'No scheduled loops yet'}</h3><p class="sa-muted">Ask a company bot in chat to prepare a loop. Review its publishing rules here before activation.</p></div>{/each}</div><div class="detail">{#if selected}<div class="sa-heading"><div><h2>{selected.name}</h2><p class="sa-muted">{selected.ownerBot.name} · revision {selected.revision}</p></div><span class="sa-badge">{selected.status.replaceAll('_',' ').toLowerCase()}</span></div><dl class="sa-details"><div><dt>Owner bot</dt><dd>{selected.ownerBot.name}</dd></div><div><dt>Next due</dt><dd>{date(selected.nextDueAt)}</dd></div><div><dt>Schedule</dt><dd>Daily at {selected.schedule.expression}</dd></div><div><dt>Time zone</dt><dd>{selected.schedule.timezone}</dd></div></dl><button on:click={()=>dispatch('openConversation',{conversationId:selected.sourceConversationId})}>Open original chat ↗</button>
 {#if editing&&patch&&base}<form on:submit|preventDefault={save}>{#if conflict}<p class="sa-warning" role="alert">The saved revision changed. Your draft is kept below; saving is blocked.</p><button type="button" on:click={()=>edit(selected)}>Discard draft and use latest saved version</button>{/if}<label class="sa-label">Loop name<input class="sa-input" bind:value={patch.name} disabled={busy||conflict} maxlength="160" required/></label><label class="sa-label">Content / generation brief<textarea class="sa-input" bind:value={patch.text} rows="5" disabled={busy||conflict}></textarea></label><label class="sa-label">Daily publishing time<input class="sa-input" type="time" step="60" bind:value={patch.schedule.expression} disabled={busy||conflict} required/></label><label class="sa-label">Time zone<input class="sa-input" value="Europe/Bucharest" readonly/><small class="sa-muted">Daily scheduling in Europe/Bucharest is currently supported.</small></label><fieldset><legend>Destinations</legend>{#each snapshot.destinations as destination}<label class="choice"><input type="checkbox" value={destination.id} bind:group={patch.destinationIds} disabled={busy||conflict||!destination.canUse&&!patch.destinationIds.includes(destination.id)}/><span>{destination.label} · {destination.platform}</span></label>{:else}<p class="sa-muted">No authorized destination choices were returned. Existing bindings are retained.</p>{/each}</fieldset><fieldset><legend>Images and videos</legend>{#each snapshot.media as media}<label class="choice"><input type="checkbox" value={media.id} bind:group={patch.mediaIds} disabled={busy||conflict||!media.canUse&&!patch.mediaIds.includes(media.id)}/><span>{media.label} · {media.kind}</span></label>{:else}<p class="sa-muted">No authorized media choices were returned. Existing media references are retained.</p>{/each}</fieldset><p class="sa-muted">Changing publishing content, destinations or schedule may require renewed authorization.</p><div class="sa-actions"><button type="button" disabled={busy} on:click={()=>{if(dirty)pendingSelection=selected.id;else{editing=false;base=null;patch=null;}}}>Cancel edit</button><button class="sa-primary" disabled={busy||conflict||!dirty||!patch.name.trim()||!patch.schedule.expression.trim()||!patch.schedule.timezone.trim()}>Save changes</button></div></form>{:else}<h3 class="subheading">Destinations</h3>{#each selected.destinations as destination}<p class="sa-muted">{destination.label} · {destination.platform}</p>{/each}<h3 class="subheading">Content brief and media</h3>{#if selected.mediaKind}<p class="sa-muted">{selected.mediaKind==='REEL'?'Generated video / reel posts':'Generated image posts'}</p>{/if}<p class="content-text">{selected.text||'No fixed text.'}</p>{#each selected.media as media}<p class="sa-muted">{media.kind==='video'?'Video':'Image'} · {media.label}</p>{/each}<h3 class="subheading">Ongoing publishing rules</h3><ul>{#each selected.rules.summary as rule}<li>{rule}</li>{/each}</ul><p class="sa-muted">{selected.rules.requiresActivation?'Human review is required before this loop may publish.':'Publishing follows the saved authorization.'}{selected.rules.expiresAt?' Authorization expires '+date(selected.rules.expiresAt)+'.':''}</p><div class="sa-actions"><button disabled={busy||!selected.actions.canEdit} on:click={()=>edit(selected)}>Edit</button><button disabled={busy||!selected.actions.canPause} on:click={()=>pause(selected)}>Pause</button><button disabled={busy||!selected.actions.canResume||!['PAUSED','UNCERTAIN'].includes(selected.status)} on:click={()=>{confirm='resume';consent=false;}}>Resume</button><button class="sa-primary" disabled={busy||!selected.actions.canActivate} on:click={()=>{confirm='activate';consent=false;}}>Review activation</button><button disabled={busy} on:click={()=>history(selected)}>Run history</button><button class="sa-danger" disabled={busy||!selected.actions.canDelete} on:click={()=>confirm='delete'}>Delete</button></div>{/if}
 {#if confirm==='activate'}<div class="sa-confirm"><strong>Authorize the displayed ongoing publishing rules?</strong><p class="sa-muted">Review this exact text, media, destinations and schedule. This authorization applies to recurring work under these rules, not arbitrary posts.</p><label class="choice"><input type="checkbox" bind:checked={consent} disabled={busy}/><span>I authorize this loop’s displayed publishing rules.</span></label><div class="sa-actions"><button disabled={busy} on:click={()=>confirm=null}>Keep awaiting review</button><button class="sa-primary" disabled={busy||!consent} on:click={()=>activate(selected)}>Authorize publishing</button></div></div>{:else if confirm==='delete'}<div class="sa-confirm"><strong>Delete this loop?</strong><p class="sa-muted">The saved loop will be removed. Previously published posts remain with their providers.</p><div class="sa-actions"><button disabled={busy} on:click={()=>confirm=null}>Keep loop</button><button class="sa-danger" disabled={busy} on:click={()=>remove(selected)}>Confirm deletion</button></div></div>{:else if confirm==='resume'}<div class="sa-confirm"><strong>Resume this loop?</strong><p class="sa-muted">Resume only the displayed schedule and previously authorized rules after the server rechecks current connections.</p><div class="sa-actions"><button disabled={busy} on:click={()=>confirm=null}>Keep paused</button><button class="sa-primary" disabled={busy} on:click={()=>resume(selected)}>Confirm resume</button></div></div>{/if}
 {#if runs!==null}<section class="runs"><h3>Run history</h3>{#each runs as run}<article><div class="sa-heading"><strong>{run.status.replaceAll('_',' ').toLowerCase()}</strong><span class="sa-muted">{date(run.startedAt)}</span></div><p class="sa-muted">Loop revision {run.loopRevision} · run {run.id}</p>{#if run.failure}<p class="sa-warning">This run needs attention. Check its recorded provider outcome before retrying.</p>{/if}{#if run.receipt?.verified}<p class="sa-muted">Verified {run.receipt.platform} receipt · {run.receipt.resourceId} · {date(run.receipt.verifiedAt)}</p>{/if}{#if run.status==='UNCERTAIN'}<p class="sa-warning">The external outcome is uncertain. No action is retried from this screen.</p>{/if}</article>{:else}<p class="sa-muted">No executions recorded for this loop.</p>{/each}</section>{/if}
 {:else}<div class="sa-empty"><h3>Select a saved loop</h3><p class="sa-muted">Review its owner bot, original chat, destinations, schedule and publishing rules.</p></div>{/if}</div></div>{/if}</section>
<style>.loops{width:100%;max-width:1250px;margin:0 auto;padding:36px 38px 60px;overflow:auto}.back{border:0!important;background:none!important;padding:0!important;color:#71809a!important}header{margin:30px 0 20px}.search{max-width:550px}.layout{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,1.4fr);gap:22px;margin-top:20px}.loop-list{min-width:0}.loop-row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;width:100%;text-align:left;margin-bottom:8px;padding:16px!important;white-space:normal}.loop-row.chosen{border-color:#a8bfff;background:#f6f8ff}.loop-row small{display:block;color:#71809a;font-size:10px;line-height:1.8;margin-top:5px}.detail{min-width:0;border:1px solid #e6ebf4;border-radius:12px;padding:22px;background:white}.detail .sa-details{padding:20px 0}.detail dd{overflow-wrap:anywhere}.subheading{margin:24px 0 10px!important}.content-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.8;color:#71809a}.detail ul{padding-left:18px;font-size:12px;line-height:1.9;color:#71809a}.detail form{margin-top:20px}.detail textarea{resize:vertical}fieldset{border:0;padding:0;margin:20px 0}legend{font-size:12px;font-weight:550;margin-bottom:9px}.choice{display:flex;align-items:flex-start;gap:9px;font-size:12px;line-height:1.8;margin:9px 0}.choice input{accent-color:#3466f6;margin-top:4px}.runs{margin-top:25px;border-top:1px solid #e6ebf4;padding-top:18px}.runs article{padding:15px 0;border-bottom:1px solid #e6ebf4}.runs .sa-heading{align-items:center}.runs .sa-heading .sa-muted{font-size:10px}@media(max-width:800px){.layout{grid-template-columns:1fr}.loops{padding:26px 22px}.detail{padding:17px}header{flex-direction:column}.loops h1{font-size:24px}.runs .sa-heading{flex-direction:column;align-items:flex-start;gap:4px}}</style>
